          "quote": "\"Our prime purpose in this life is to help others and if you can't help them, at least don't hurt them.\"",
          "quoteSource": "– Dalai Lama",
          "labels": {
            "s1": "Step 1",
            "s2": "Step 2",
            "s3": "Step 3",
            "s4": "Step 4",
            "s5": "Step 5",
            "s6": "Step 6",
            "s7": "Step 7",
            "s8": "Step 8",
            "s9": "Step 9",
            "s10": "Step 10",
            "s11": "Step 11",
            "s12": "Step 12"
          },
          "text": {
            "s1": "I admitted I was powerless over my condition — <strong>my life had become unmanageable</strong>.",
            "s2": "I came to believe that <strong>a Power greater than myself could restore me to sanity</strong>.",
            "s3": "I made a decision to <strong>turn my will and my life over</strong> to the care of a higher power.",
            "s4": "I made a searching and fearless <strong>moral inventory of myself</strong> and my actions.",
            "s5": "I <strong>admitted to my higher power, to myself</strong> and to another human being the exact nature of my wrongs.",
            "s6": "I'm <strong>entirely ready to have my higher power remove</strong> all these defects of character.",
            "s7": "I <strong>humbly asked my higher power</strong> to remove my shortcomings.",
            "s8": "I made a <strong>list of all persons I had harmed</strong>, and became willing to make amends to them all.",
            "s9": "I made <strong>direct amends</strong> wherever possible, except when to do so would injure them or others.",
            "s10": "I continued to <strong>take personal inventory</strong> and when I was wrong I promptly admitted it.",
            "s11": "I sought <strong>through prayer and meditation</strong> to improve my conscious contact with my higher power, praying only for knowledge of their will for me.",
            "s12": "I had a <strong>spiritual awakening as the result of these steps</strong> and tried to carry this message to others learning to live with bipolar."
          },
          "modal": {
            "group1Title": "Steps 1–3 · I am powerless over my condition",
            "group2Title": "Steps 4–10 · Making amends for past actions",
            "group3Title": "Steps 11–12 · Carrying hope to others"
          }
