        about: { subtitle: 'Un espacio seguro para personas con bipolar', body: 'Esta es una comunidad anónima para personas con trastorno bipolar.', guidelinesTitle: 'Normas de la comunidad', guidelinesList: "⚠️ &nbsp;Cero tolerancia con el contenido objetable o los usuarios abusivos (18+)<br>💛 &nbsp;Sé amable — todos aquí lo están haciendo lo mejor que pueden<br>🔒 &nbsp;Respeta la privacidad de los demás — no compartas datos personales<br>🆘 &nbsp;Usa la marca SOS si te preocupa de verdad alguien<br>🚨 &nbsp;Denuncia las publicaciones que incumplen las normas — se revisan en 24 horas<br>🙈 &nbsp;Silencia a quien prefieras no leer — sus publicaciones desaparecen para ti", viewTerms: "Ver términos completos", reportProblem: "Informar de un problema:", postActionsTitle: "Acciones de publicación", postActionsList: "💛 &nbsp;<strong>Me gusta</strong> — muestra cariño a una publicación (no puedes darte a la tuya)<br>💬 &nbsp;<strong>Comentar</strong> — lee las respuestas y únete a la conversación<br>🆘 &nbsp;<strong>SOS</strong> — avisa discretamente a un moderador si te preocupa alguien<br>🚨 &nbsp;<strong>Denunciar</strong> — marca una publicación que incumple las normas — se revisan en 24 horas<br>🙈 &nbsp;<strong>Silenciar</strong> — oculta todo de un usuario, solo en tu dispositivo<br>🗑️ &nbsp;<strong>Eliminar</strong> — borra una de tus propias publicaciones (se muestra tenue en tus publicaciones)", moderatorsTitle: "Solo moderadores", moderatorsList: "📌 &nbsp;<strong>Fijar</strong> — fija una publicación al principio de la pestaña (toca de nuevo para desfijar)<br>🗑️ &nbsp;<strong>Eliminar</strong> — quita cualquier publicación del tablón<br>🚫 &nbsp;<strong>Vetar</strong> — veta temporalmente a un usuario para que no publique", mutedTitle: "Usuarios silenciados", poweredTitle: 'Desarrollado por BipolarBear', poweredBody: 'BipolarBear es un diario de ánimo gratuito para personas con trastorno bipolar.', discover: '🐻 Descubrir BipolarBear →', close: 'Cerrar' },
