          "manicTitle": "🚀 Maniaque (9–10)",
          "manicBipolarUk": "<strong>Échelle Bipolar UK 9–10 :</strong> Manie sévère — une hospitalisation est souvent nécessaire. Suractivité majeure, fuite des idées, désinhibition marquée, sommeil très réduit ou absent. Délires de grandeur, hallucinations possibles. Aucune conscience de son état.",
          "manicAction": "🚨 Bloquez toutes vos cartes bancaires, arrêtez tout, restez chez vous.",
          "elevatedTitle": "😄 Élevée / Hypomaniaque (7–8)",
          "elevatedBipolarUk": "<strong>Échelle Bipolar UK 7–8 :</strong> Humeur élevée, suractivité marquée, besoin de sommeil réduit (mais pas absent), énergie, libido et confiance accrues. Décisions impulsives. Encore partiellement fonctionnel mais jugement altéré.",
          "elevatedAction": "🧠 Réfléchissez avant d'agir. Attendez un peu avant de prendre une décision.",
          "goodTitle": "😊 Bonne / Stable (5–6)",
          "goodBipolarUk": "<strong>Échelle Bipolar UK 5–6 :</strong> Humeur normale et stable. Bonne énergie, motivation et concentration. Capable de bien fonctionner au travail et socialement. Sommeil normal. C'est l'état recherché.",
          "goodAction": "✅ Profitez de l'instant. Gardez les choses sous contrôle.",
          "neutralTitle": "😐 Neutre (4)",
          "neutralBody": "Tout à fait stable. Aucun signe de manie ni de dépression. Léger repli et concentration moindre, mais gérable au quotidien.",
          "neutralBipolarUk": "<strong>Échelle Bipolar UK 4 :</strong> Légèrement en dessous de la normale — léger repli, humeur un peu basse mais on tient bon au quotidien. Pas d'altération majeure.",
          "neutralAction": "✅ C'est l'état de référence. Profitez-en.",
