          "text": {
            "s1": "J'ai admis que j'étais impuissant face à ma condition — <strong>ma vie était devenue ingérable</strong>.",
            "s2": "J'en suis venu à croire qu'une <strong>Puissance plus grande que moi pouvait me rendre la raison</strong>.",
            "s3": "J'ai décidé de <strong>confier ma volonté et ma vie</strong> aux soins d'une puissance supérieure.",
            "s4": "J'ai fait un <strong>inventaire moral approfondi et sans peur de moi-même</strong> et de mes actes.",
            "s5": "J'ai <strong>avoué à ma puissance supérieure, à moi-même</strong> et à un autre être humain la nature exacte de mes torts.",
            "s6": "Je suis <strong>tout à fait prêt à ce que ma puissance supérieure élimine</strong> tous ces défauts de caractère.",
            "s7": "J'ai <strong>humblement demandé à ma puissance supérieure</strong> d'éliminer mes défauts.",
            "s8": "J'ai dressé une <strong>liste de toutes les personnes que j'avais blessées</strong> et je suis devenu prêt à réparer mes torts envers elles toutes.",
            "s9": "J'ai <strong>réparé directement mes torts</strong> chaque fois que c'était possible, sauf lorsque cela aurait pu leur nuire ou nuire à autrui.",
            "s10": "J'ai poursuivi mon <strong>inventaire personnel</strong> et, lorsque j'avais tort, je l'ai promptement admis.",
            "s11": "J'ai cherché, <strong>par la prière et la méditation</strong>, à améliorer mon contact conscient avec ma puissance supérieure, priant seulement pour connaître sa volonté à mon égard.",
            "s12": "J'ai connu un <strong>éveil spirituel à l'issue de ces étapes</strong> et j'ai essayé de transmettre ce message à d'autres personnes apprenant à vivre avec la bipolarité."
          },
