        about: { subtitle: 'Ein sicherer Ort für Menschen mit Bipolar', body: 'Eine anonyme Community für Menschen mit bipolarer Störung.', guidelinesTitle: 'Community-Richtlinien', guidelinesList: "⚠️ &nbsp;Null Toleranz für anstößige Inhalte oder missbräuchliche Nutzer (18+)<br>💛 &nbsp;Seien Sie freundlich — hier gibt jeder sein Bestes<br>🔒 &nbsp;Respektieren Sie die Privatsphäre anderer — teilen Sie keine persönlichen Daten<br>🆘 &nbsp;Nutzen Sie das SOS-Signal, wenn Sie sich ernsthaft um jemanden sorgen<br>🚨 &nbsp;Melden Sie Beiträge, die gegen die Regeln verstoßen — innerhalb von 24 Stunden geprüft<br>🙈 &nbsp;Schalten Sie jeden stumm, von dem Sie lieber nichts lesen möchten — seine Beiträge verschwinden für Sie", viewTerms: "Vollständige AGB anzeigen", reportProblem: "Ein Problem melden:", postActionsTitle: "Beitragsaktionen", postActionsList: "💛 &nbsp;<strong>Gefällt mir</strong> — zeigen Sie einem Beitrag etwas Liebe (Ihre eigenen können Sie nicht liken)<br>💬 &nbsp;<strong>Kommentieren</strong> — lesen Sie Antworten und beteiligen Sie sich am Gespräch<br>🆘 &nbsp;<strong>SOS</strong> — benachrichtigen Sie einen Moderator diskret, wenn Sie sich um jemanden sorgen<br>🚨 &nbsp;<strong>Melden</strong> — markieren Sie einen Beitrag, der gegen die Regeln verstößt — innerhalb von 24 Stunden geprüft<br>🙈 &nbsp;<strong>Stummschalten</strong> — blenden Sie alles von einem Nutzer aus, nur auf Ihrem Gerät<br>🗑️ &nbsp;<strong>Entfernen</strong> — löschen Sie einen Ihrer eigenen Beiträge (auf Ihren Beiträgen blass angezeigt)", moderatorsTitle: "Nur Moderatoren", moderatorsList: "📌 &nbsp;<strong>Anheften</strong> — heften Sie einen Beitrag oben im Tab an (erneut tippen zum Lösen)<br>🗑️ &nbsp;<strong>Löschen</strong> — entfernen Sie jeden Beitrag vom Board<br>🚫 &nbsp;<strong>Sperren</strong> — sperren Sie einen Nutzer vorübergehend vom Posten", mutedTitle: "Stummgeschaltete Nutzer", poweredTitle: 'Powered by BipolarBear', poweredBody: 'BipolarBear ist ein kostenloses Stimmungstagebuch für Menschen mit bipolarer Störung.', discover: '🐻 BipolarBear entdecken →', close: 'Schließen' },
