        about: { subtitle: 'Uno spazio sicuro per le persone con bipolare', body: 'Una comunità anonima per persone con disturbo bipolare.', guidelinesTitle: 'Linee guida della comunità', guidelinesList: "⚠️ &nbsp;Tolleranza zero per contenuti discutibili o utenti abusivi (18+)<br>💛 &nbsp;Sii gentile — qui ognuno fa del suo meglio<br>🔒 &nbsp;Rispetta la privacy degli altri — non condividere dati personali<br>🆘 &nbsp;Usa il segnale SOS se sei davvero preoccupato per qualcuno<br>🚨 &nbsp;Segnala i post che infrangono le regole — esaminati entro 24 ore<br>🙈 &nbsp;Silenzia chiunque preferiresti non leggere — i suoi post spariscono per te", viewTerms: "Vedi i Termini completi", reportProblem: "Segnala un problema:", postActionsTitle: "Azioni sul post", postActionsList: "💛 &nbsp;<strong>Mi piace</strong> — mostra affetto a un post (non puoi mettere mi piace ai tuoi)<br>💬 &nbsp;<strong>Commenta</strong> — leggi le risposte e unisciti alla conversazione<br>🆘 &nbsp;<strong>SOS</strong> — avvisa discretamente un moderatore se sei preoccupato per qualcuno<br>🚨 &nbsp;<strong>Segnala</strong> — segnala un post che infrange le regole — esaminato entro 24 ore<br>🙈 &nbsp;<strong>Silenzia</strong> — nascondi tutto di un utente, solo sul tuo dispositivo<br>🗑️ &nbsp;<strong>Rimuovi</strong> — elimina uno dei tuoi post (mostrato in trasparenza sui tuoi post)", moderatorsTitle: "Solo moderatori", moderatorsList: "📌 &nbsp;<strong>Fissa</strong> — fissa un post in cima alla scheda (tocca di nuovo per rimuoverlo)<br>🗑️ &nbsp;<strong>Elimina</strong> — rimuovi qualsiasi post dalla bacheca<br>🚫 &nbsp;<strong>Banna</strong> — banna temporaneamente un utente dalla pubblicazione", mutedTitle: "Utenti silenziati", poweredTitle: 'Powered by BipolarBear', poweredBody: 'BipolarBear è un diario dell\'umore gratuito per persone con disturbo bipolare.', discover: '🐻 Scopri BipolarBear →', close: 'Chiudi' },
