        about: { subtitle: 'Een veilige plek voor mensen met bipolariteit', body: 'Een anonieme community voor mensen met een bipolaire stoornis.', guidelinesTitle: 'Community richtlijnen', guidelinesList: "⚠️ &nbsp;Geen enkele tolerantie voor aanstootgevende inhoud of misbruikende gebruikers (18+)<br>💛 &nbsp;Wees vriendelijk — iedereen hier doet zijn best<br>🔒 &nbsp;Respecteer de privacy van anderen — deel geen persoonlijke gegevens<br>🆘 &nbsp;Gebruik het SOS-signaal als u zich echt zorgen maakt om iemand<br>🚨 &nbsp;Meld berichten die de regels overtreden — binnen 24 uur beoordeeld<br>🙈 &nbsp;Demp iedereen van wie u liever niets leest — hun berichten verdwijnen voor u", viewTerms: "Volledige voorwaarden bekijken", reportProblem: "Een probleem melden:", postActionsTitle: "Berichtacties", postActionsList: "💛 &nbsp;<strong>Leuk</strong> — geef een bericht wat liefde (u kunt uw eigen bericht niet liken)<br>💬 &nbsp;<strong>Reageren</strong> — lees reacties en doe mee met het gesprek<br>🆘 &nbsp;<strong>SOS</strong> — waarschuw stilletjes een moderator als u zich zorgen maakt om iemand<br>🚨 &nbsp;<strong>Melden</strong> — markeer een bericht dat de regels overtreedt — binnen 24 uur beoordeeld<br>🙈 &nbsp;<strong>Dempen</strong> — verberg alles van een gebruiker, alleen op uw apparaat<br>🗑️ &nbsp;<strong>Verwijderen</strong> — verwijder een van uw eigen berichten (vaag weergegeven op uw berichten)", moderatorsTitle: "Alleen moderators", moderatorsList: "📌 &nbsp;<strong>Vastzetten</strong> — zet een bericht bovenaan het tabblad vast (tik nogmaals om los te maken)<br>🗑️ &nbsp;<strong>Verwijderen</strong> — verwijder elk bericht van het bord<br>🚫 &nbsp;<strong>Verbannen</strong> — verban een gebruiker tijdelijk van het plaatsen", mutedTitle: "Gedempte gebruikers", poweredTitle: 'Powered by BipolarBear', poweredBody: 'BipolarBear is een gratis stemmingsdagboek voor mensen met een bipolaire stoornis.', discover: '🐻 Ontdek BipolarBear →', close: 'Sluiten' },
