          samaritansFree: '116 123 · 免费，24/7',
          emergencyContact: '紧急联系人',
          continueLogging: '继续记录',
          favTitle: '⭐ 收藏的记录',
          setPinTitle: '🔒 设置 PIN',
          disablePin: '禁用 PIN',
          protectData: '保护你的数据',
          choosePinDesc: '选择一个 4 位数的 PIN 来锁定你的日记。',
          pinEncryptNote: '你的 PIN 会加密此设备上的数据。如果你忘记了 PIN，你的记录将无法恢复。',
          onThisDay: '⭐ 那一天',
          showAgainNextYear: '明年再显示',
          offlineBanner: '📶 离线 — 新条目将在重新连接时同步',
          survivalKitTip: '生存工具包',
          changeDateTip: '更改日期',
          favouriteTip: '收藏',
          switchToFocused: '切换到专注模式',
          fmExit: '✕ 退出',
          fmSkip: '跳过 →',
          fmNext: '下一步 →',
          reducedMotion: '减弱动态',
          reducedMotionTip: '由于您的设备已开启"减弱动态效果"，动画已减少。',
          goToSaveTip: '前往保存',
          deleteDraftTip: '删除草稿',
          importHealthTitle: '导入健康数据',
          importHealthDesc: '从手机的健康应用导入数据。',
          importSleep: '😴 导入睡眠',
          importSteps: '🏃 导入步数',
          mobileOnly: '仅限移动应用',
